import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor triplet_margin_loss_forward(torch::Tensor anchor,
                                           torch::Tensor positive,
                                           torch::Tensor negative,
                                           double margin);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void triplet_margin_loss_row_kernel(
    const float* __restrict__ A,
    const float* __restrict__ P,
    const float* __restrict__ N,
    float* __restrict__ row_loss,
    int64_t batch, int64_t dim, float margin)
{
  // Warp-per-row reduction: each warp independently processes one row at a
  // time and reduces purely via warp shuffles (no shared memory, no
  // __syncthreads()). The previous one-block-per-row design required all
  // warps in a block to rendezvous through shared memory and a block-wide
  // barrier, which the profiler showed collapsed achieved occupancy to
  // ~15% (vs 100% theoretical) because resident warps stalled waiting on
  // slower sibling warps within the same block. With fully independent
  // warps, the warp scheduler can issue any resident warp at any time,
  // removing the cross-warp synchronization bottleneck and dramatically
  // improving achieved occupancy and hardware utilization.
  int64_t dim4 = dim / 4;
  int lane = threadIdx.x & 31;
  int warp_in_block = threadIdx.x >> 5;
  int warps_per_block = blockDim.x >> 5;
  int64_t global_warp = (int64_t)blockIdx.x * warps_per_block + warp_in_block;
  int64_t total_warps = (int64_t)gridDim.x * warps_per_block;
  for (int64_t row = global_warp; row < batch; row += total_warps) {
    const float* a_ptr = A + row * dim;
    const float* p_ptr = P + row * dim;
    const float* n_ptr = N + row * dim;
    // Represent rows as vectorized float4 CuTe tensors for coalesced loads
    auto mA = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(a_ptr)),
                          make_shape(dim4), make_stride(Int<1>{}));
    auto mP = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(p_ptr)),
                          make_shape(dim4), make_stride(Int<1>{}));
    auto mN = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(n_ptr)),
                          make_shape(dim4), make_stride(Int<1>{}));
    float sum_ap = 0.0f;
    float sum_an = 0.0f;
    for (int64_t i = lane; i < dim4; i += 32) {
      float4 a4 = mA(i);
      float4 p4 = mP(i);
      float4 n4 = mN(i);
      float dx;
      dx = a4.x - p4.x; sum_ap += dx * dx;
      dx = a4.y - p4.y; sum_ap += dx * dx;
      dx = a4.z - p4.z; sum_ap += dx * dx;
      dx = a4.w - p4.w; sum_ap += dx * dx;
      dx = a4.x - n4.x; sum_an += dx * dx;
      dx = a4.y - n4.y; sum_an += dx * dx;
      dx = a4.z - n4.z; sum_an += dx * dx;
      dx = a4.w - n4.w; sum_an += dx * dx;
    }
    // Warp-level reduction only; no shared memory / __syncthreads() needed
    // since a single warp owns the entire row.
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      sum_ap += __shfl_down_sync(0xffffffff, sum_ap, offset);
      sum_an += __shfl_down_sync(0xffffffff, sum_an, offset);
    }
    if (lane == 0) {
      float dap = sqrtf(sum_ap);
      float dan = sqrtf(sum_an);
      float loss = dap - dan + margin;
      loss = loss > 0.0f ? loss : 0.0f;
      row_loss[row] = loss;
    }
  }
}
__global__ void reduce_mean_kernel(
    const float* __restrict__ row_loss,
    float* __restrict__ out,
    int64_t batch)
{
  __shared__ float shared[32];
  float local_sum = 0.0f;
  for (int64_t i = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
       i < batch;
       i += (int64_t)gridDim.x * blockDim.x) {
    local_sum += row_loss[i];
  }
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    local_sum += __shfl_down_sync(0xffffffff, local_sum, offset);
  }
  int lane = threadIdx.x % 32;
  int wid  = threadIdx.x / 32;
  if (lane == 0) shared[wid] = local_sum;
  __syncthreads();
  int numWarps = (blockDim.x + 31) / 32;
  if (wid == 0) {
    local_sum = (lane < numWarps) ? shared[lane] : 0.0f;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      local_sum += __shfl_down_sync(0xffffffff, local_sum, offset);
    }
    if (lane == 0) {
      atomicAdd(out, local_sum / (float)batch);
    }
  }
}
torch::Tensor triplet_margin_loss_forward(torch::Tensor anchor,
                                           torch::Tensor positive,
                                           torch::Tensor negative,
                                           double margin) {
  TORCH_CHECK(anchor.is_cuda() && positive.is_cuda() && negative.is_cuda(),
              "All inputs must be CUDA tensors");
  TORCH_CHECK(anchor.scalar_type() == at::kFloat &&
              positive.scalar_type() == at::kFloat &&
              negative.scalar_type() == at::kFloat,
              "Expect float32 tensors");
  TORCH_CHECK(anchor.dim() == 2 && positive.dim() == 2 && negative.dim() == 2,
              "Inputs must be 2D [batch, dim]");
  TORCH_CHECK(anchor.sizes() == positive.sizes() && anchor.sizes() == negative.sizes(),
              "anchor, positive, negative must have same shape");
  auto a_c = anchor.contiguous();
  auto p_c = positive.contiguous();
  auto n_c = negative.contiguous();
  int64_t batch = a_c.size(0);
  int64_t dim   = a_c.size(1);
  TORCH_CHECK(dim % 4 == 0, "dim must be divisible by 4 for vectorized load");
  auto out = torch::empty({}, a_c.options());
  auto row_loss = torch::empty({batch}, a_c.options());
  int threads = 128; // 4 warps per block
  int warps_per_block = threads / 32;
  // Each warp independently reduces one full row using only warp shuffles
  // (no shared memory, no __syncthreads()), so unlike the previous
  // one-block-per-row design there is no cross-warp barrier that can stall
  // resident warps. This removes the achieved-occupancy collapse (~15%
  // vs 100% theoretical) that was caused by blocks waiting on
  // __syncthreads(), and lets the warp scheduler freely interleave any
  // resident warp. The grid-stride loop over warps still covers the
  // entire batch regardless of grid size.
  int64_t warps_needed = batch;
  int64_t grid_blocks = (warps_needed + warps_per_block - 1) / warps_per_block;
  if (grid_blocks < 1) grid_blocks = 1;
  dim3 grid((unsigned)grid_blocks);
  dim3 block((unsigned)threads);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  cudaMemsetAsync(out.data_ptr<float>(), 0, sizeof(float), stream);
  triplet_margin_loss_row_kernel<<<grid, block, 0, stream>>>(
      a_c.data_ptr<float>(),
      p_c.data_ptr<float>(),
      n_c.data_ptr<float>(),
      row_loss.data_ptr<float>(),
      batch, dim, (float)margin
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "triplet_margin_loss_row_kernel launch failed: ", cudaGetErrorString(err));
  int reduce_threads = 256;
  int64_t reduce_blocks_i64 = (batch + reduce_threads - 1) / reduce_threads;
  if (reduce_blocks_i64 > 1024) reduce_blocks_i64 = 1024;
  if (reduce_blocks_i64 < 1) reduce_blocks_i64 = 1;
  int reduce_blocks = (int)reduce_blocks_i64;
  reduce_mean_kernel<<<reduce_blocks, reduce_threads, 0, stream>>>(
      row_loss.data_ptr<float>(),
      out.data_ptr<float>(),
      batch
  );
  err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "reduce_mean_kernel launch failed: ", cudaGetErrorString(err));
  return out;
}
"""

triplet_ext = load_inline(
    name="cute_triplet_margin_loss_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["triplet_margin_loss_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Computes Triplet Margin Loss using a single fused custom CUDA/CUTE kernel.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)
        self._ext = triplet_ext

    def forward(self, anchor, positive, negative):
        return self._ext.triplet_margin_loss_forward(
            anchor, positive, negative, self.margin
        )

